g=[[8]*18 for _ in range(12)]
pts=[(2,6),(2,12),(3,13),(4,13),(5,6),(5,7),(5,8),(5,10),(5,11),(5,12),(7,6),(8,13),(10,6),(10,12),(10,13)]
for r,c in pts:g[r][c]=4
# fill strictly between pairs of markers in same row/col
for r in range(12):
 cs=[c for rr,c in pts if rr==r]
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b):
   if g[r][c]==8:g[r][c]=2
for c in range(18):
 rs=[r for r,cc in pts if cc==c]
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b):
   if g[r][c]==8:g[r][c]=2
print(g)
